   {owner!==actorId&&<div className="workflow-note"><p>Estás viendo la semana de <strong>{(weekData?.members??d.members).find((m:Row)=>m.id===owner)?.name}</strong>. {coord?'Los cambios en otro plan requieren un motivo.':'Podés consultar este plan. Para planificar el tuyo, volvé a Mi semana.'} <button className="text-button" onClick={()=>navigate('Mi semana')}>Volver a mi semana</button></p></div>}{weekClosed?<div className="info-banner"><ShieldCheck size={20}/><div><strong>Semana cerrada · versión {snapshotVersion||selectedWeek?.closeVersion}</strong><p>Estás viendo los textos, responsables y resultados conservados al cierre.</p></div><select aria-label="Versión histórica" value={snapshotVersion||selectedWeek?.closeVersion} onChange={e=>setSnapshotVersion(Number(e.target.value))}>{s.snapshots.filter(sn=>sn.kind==='week'&&sn.targetId===week).map(sn=><option key={sn.id} value={sn.version}>Versión {sn.version}</option>)}</select>{coord&&<button className="btn" onClick={()=>openCommand('Reabrir semana',{kind:'reopen_week',expectedVersion:selectedWeek!.version},[reasonField],{weekId:week})}>Reabrir</button>}</div>:(weekCommitments.length>0||plan?.confirmedAt)?<div className={'plan-banner '+(plan?.confirmedAt?'confirmed':'')}><span className="plan-icon">{plan?.confirmedAt?<CheckCheck size={23}/>:<CalendarDays size={23}/>}</span><div><strong>{plan?.confirmedAt?'Planificación confirmada':'Planificación sin confirmar'}</strong><p>{plan?.confirmedAt?'Las incorporaciones posteriores se distinguen del acuerdo inicial.':'Revisá los avances que acordaste y confirmá la planificación inicial.'}</p></div>{ownWeek&&(!plan?.confirmedAt)&&<button className="btn primary" onClick={()=>openCommand('Confirmar planificación',{kind:'confirm_plan'},owner!==actorId?[reasonField]:[],{weekId:week,ownerId:owner},'Se guardará una copia de los resultados, responsables y prioridades iniciales.','Confirmar planificación')}>Confirmar planificación <Check size={15}/></button>}</div>:null}
